require_once __DIR__.'/google-head.php';
require_once __DIR__.'/js-compat.php';require_once __DIR__.'/render-templates.php';
function seoHead($s,$p,$title,$description,$status,$path){$seo=$p['seo']??[];$canonical=SITE_ORIGIN.($p?publicPath($p):$path);$metaTitle=trim($seo['title']??'')?:($title===$s['name']?$title:$title.' | '.$s['name']);$summary=trim($seo['description']??'')?:mb_substr(plain($description?:($p['experience']['summary']??$s['shortDescription'])),0,170);$noindex=$status!==200||($seo['noindex']??false)||in_array($path,['/search.php','/booking.php','/dashboard','/thank-you'])||isset($_GET['q'])||isset($_GET['city']);$raw=$seo['socialImage']??'';$raw=$raw?:($p['images'][0]['src']??'/assets/images/dubai-uae-tours-hero.webp');$social=str_starts_with($raw,'https://')?$raw:SITE_ORIGIN.$raw;$logo=str_starts_with($s['logo'],'https://')?$s['logo']:SITE_ORIGIN.$s['logo'];$business=['@type'=>'TravelAgency','@id'=>SITE_ORIGIN.'/#business','name'=>$s['name'],'url'=>SITE_ORIGIN,'telephone'=>$s['phone'],'email'=>$s['email'],'logo'=>$logo,'address'=>['@type'=>'PostalAddress','streetAddress'=>$s['address'],'addressLocality'=>'Dubai','addressCountry'=>'AE'],'sameAs'=>array_values(array_filter([$s['facebook'],$s['instagram'],$s['threads'],$s['linkedin']],fn($u)=>str_starts_with($u,'https://')))];$graph=[$business,['@type'=>'WebSite','@id'=>SITE_ORIGIN.'/#website','url'=>SITE_ORIGIN,'name'=>$s['name'],'publisher'=>['@id'=>SITE_ORIGIN.'/#business']]];if(!$noindex){$node=['@type'=>($p['type']??'')==='guide'?'BlogPosting':'WebPage','@id'=>$canonical.'#page','url'=>$canonical,'name'=>$metaTitle,'headline'=>$p['title']??$title,'description'=>$summary,'image'=>$social,'isPartOf'=>['@id'=>SITE_ORIGIN.'/#website'],'publisher'=>['@id'=>SITE_ORIGIN.'/#business']];if(($p['type']??'')==='guide')$node+=['datePublished'=>$p['publishedAt'],'author'=>['@type'=>'Person','name'=>$p['author']?:$s['name']],'mainEntityOfPage'=>$canonical];if(!empty($p['modifiedAt']))$node['dateModified']=$p['modifiedAt'];$graph[]=$node;if(in_array($p['type']??'',['tour','attraction']))$graph[]=['@type'=>'TouristTrip','name'=>$p['title'],'description'=>$p['experience']['summary'],'url'=>$canonical,'image'=>$social,'provider'=>['@id'=>SITE_ORIGIN.'/#business']];if($path!=='/')$graph[]=['@type'=>'BreadcrumbList','itemListElement'=>[['@type'=>'ListItem','position'=>1,'name'=>'Home','item'=>SITE_ORIGIN.'/'],['@type'=>'ListItem','position'=>2,'name'=>$p['title']??$title,'item'=>$canonical]]];}
return googleHeadTags().($path==='/thank-you'?'<link rel="stylesheet" href="/thank-you.css?v=1">':'').'<title>'.e($metaTitle).'</title><meta name="description" content="'.e($summary).'"><link rel="canonical" href="'.e($canonical).'"><meta name="robots" content="'.($noindex?'noindex,follow':'index,follow,max-image-preview:large').'"><meta property="og:type" content="'.(($p['type']??'')==='guide'?'article':'website').'"><meta property="og:site_name" content="'.e($s['name']).'"><meta property="og:title" content="'.e($metaTitle).'"><meta property="og:description" content="'.e($summary).'"><meta property="og:url" content="'.e($canonical).'"><meta property="og:image" content="'.e($social).'"><meta name="twitter:card" content="summary_large_image"><meta name="twitter:title" content="'.e($metaTitle).'"><meta name="twitter:description" content="'.e($summary).'"><meta name="twitter:image" content="'.e($social).'"><script type="application/ld+json">'.json_encode(['@context'=>'https://schema.org','@graph'=>$graph],JSON_HEX_TAG|JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE).'</script>';}
function optimizeImages($html,$pages){$manifest=json_decode(file_get_contents(__DIR__.'/image-manifest.json'),true);foreach($pages as $p)foreach($p['images'] as $img)if(!isset($manifest[$img['src']])&&!empty($img['width'])&&!empty($img['height']))$manifest[$img['src']]=['width'=>$img['width'],'height'=>$img['height'],'variants'=>[['src'=>$img['src'],'width'=>$img['width']]]];return preg_replace_callback('/<img\b([^>]*)>/i',function($m)use($manifest){if(!preg_match('/\bsrc="([^"]+)"/',$m[1],$src)||!isset($manifest[$src[1]]))return str_replace('<img','<img decoding="async"',$m[0]);$i=$manifest[$src[1]];$hero=str_contains($m[1],'hero-background');$detail=str_contains($m[1],'detail-media')||str_contains($m[1],'article-hero');$aboveFold=$hero||$detail;$logo=str_contains($src[1],'best-tours-dubai-logo');$max=end($i['variants']);$small=$max;foreach($i['variants'] as $v)if($v['width']>=960){$small=$v;break;}$attrs=preg_replace('/\bsrc="[^"]+"/','src="'.e(($hero?$max:$small)['src']).'"',$m[1]);$attrs=preg_replace('/\s(?:width|height|srcset|sizes|decoding|fetchpriority)="[^"]*"/','',$attrs);$sizes=$logo?'260px':($hero?'100vw':($detail?'(max-width:900px) 100vw, 55vw':'(max-width:600px) 100vw, (max-width:900px) 50vw, 33vw'));$attrs.=' width="'.$i['width'].'" height="'.$i['height'].'" srcset="'.e(implode(', ',array_map(fn($x)=>$x['src'].' '.$x['width'].'w',$i['variants']))).'" sizes="'.$sizes.'" decoding="async"'.($hero?' fetchpriority="high"':'');if($aboveFold){$attrs=preg_replace('/\sloading="[^"]*"/','',$attrs);$attrs.=' loading="eager"';}return '<img'.$attrs.'>';},$html);}
function rewriteLinks($html,$pages){$links=['/category/general'=>'/dubai-safari-park-tour','/dubai-night-city-tour'=>'/category/city-tours'];foreach($pages as $p)foreach(array_merge([$p['path']],$p['aliases']??[]) as $x)$links[$x]=publicPath($p);return preg_replace_callback('~href="(?:https://safaridubaipark.com)?(/[^"?#]*)([^" ]*)"~',fn($m)=>isset($links[$m[1]])?'href="'.e($links[$m[1]]).$m[2].'"':$m[0],$html);}
function publicSite($path){global $categoryNames;$data=allContent();$s=$data['settings'];$pages=$data['pages'];$query=parse_url($_SERVER['REQUEST_URI'],PHP_URL_QUERY);$suffix=$query?'?'.$query:'';
if($path==='/robots.txt'){header('Content-Type: text/plain');echo "User-agent: *\nDisallow: /dashboard\nDisallow: /api/\nDisallow: /auth/\nSitemap: ".SITE_ORIGIN."/sitemap-index.xml\n";exit;}
if(in_array($path,['/sitemap.xml','/sitemap-index.xml','/sitemaps/pages.xml','/sitemaps/tours.xml','/sitemaps/attractions.xml','/sitemaps/guides.xml'],true)){require_once __DIR__.'/seo-sitemaps.php';serveSeoSitemap($path,$pages);}
foreach($pages as $p){if(in_array($path,$p['aliases']??[],true)||($p['path']===$path&&publicPath($p)!==$path)){header('Location: '.publicPath($p).$suffix,true,301);exit;}if(publicPath($p)===$path)$path=$p['path'];}
if(in_array($path,['/dubai-city-tour','/dubai-night-city-tour'])){header('Location: /category/city-tours'.$suffix,true,301);exit;}if($path==='/safari-dubai-park'){header('Location: /dubai-safari-park-tour'.$suffix,true,301);exit;}
if($path==='/category/general'){header('Location: /dubai-safari-park-tour'.$suffix,true,301);exit;}
$visible=array_values(array_filter($pages,fn($p)=>$p['status']==='published'&&(empty($p['publishedAt'])||strtotime($p['publishedAt'])<=time())));$page=null;foreach($visible as $p)if($p['path']===$path){$page=$p;break;}$title=$s['name'];$description='';$body='';$script='';$status=200;
if($path==='/thank-you'){require_once __DIR__.'/thank-you.php';$title='Thank you for your booking request';$body=thankYouPage($s);}elseif($path==='/')$body=home($visible,$s);elseif($path==='/booking.php'){$slug=$_GET['tour']??$_GET['attraction']??'';$p=null;foreach($visible as $x)if(in_array($x['type'],['tour','attraction'])&&(basename($x['path'])===$slug||basename(publicPath($x))===$slug)){$p=$x;break;}if($p){$title='Book '.$p['title'];$result=booking($p,$s,$_GET['package']??null);$body=$result['body'];$script=$result['script'];}else{$status=404;$title='Experience not found';}}
elseif(in_array($path,['/attractions.php','/search.php','/blog'])||str_starts_with($path,'/category/')){$c=explode('/',$path)[2]??'';$q=trim($_GET['q']??'');$city=$_GET['city']??'';$title=$path==='/blog'?($page['title']??'Dubai travel guides'):($path==='/attractions.php'?($page['title']??'Dubai & Abu Dhabi attraction tickets'):($path==='/search.php'?'Find your next experience':($categoryNames[$c]??'Experiences')));$results=[];foreach($visible as $p){$matches=$path==='/blog'?$p['type']==='guide':($path==='/attractions.php'?$p['type']==='attraction':(str_starts_with($path,'/category/')?in_array($p['type'],['tour','attraction'])&&$p['category']===$c:in_array($p['type'],['tour','attraction','guide'])));$hay=strtolower($p['title'].' '.$p['experience']['summary'].' '.$p['experience']['location']);foreach(preg_split('/\s+/u',strtolower($q)) as $term)if(!str_contains($hay,$term))$matches=false;if($city&&!str_contains(strtolower($p['experience']['location']),strtolower($city)))$matches=false;if($matches)$results[]=$p;}$body=breadcrumb($title).'<main id="main" class="container listing"><p class="kicker">FIND YOUR NEXT DUBAI STORY</p><h1>'.e($title).'</h1>'.(!empty($page['contentHtml'])?'<article class="rich-content">'.cleanHtml($page['contentHtml']).'</article>':'').'<form class="listing-search"><label>Search<input name="q" value="'.e($q).'" type="search" placeholder="Experience or destination"></label>';if($path==='/attractions.php'){$body.='<label>City<select name="city"><option value="">All cities</option>';foreach(['Dubai','Abu Dhabi'] as $x)$body.='<option '.($city===$x?'selected':'').'>'.$x.'</option>';$body.='</select></label>';}$body.='<button class="button">Search</button></form><p class="result-count">'.count($results).' '.($path==='/blog'?'guides':'experiences').' to explore</p>'.($results?grid($results):'<div class="empty"><h2>No matches found</h2><p>Try another destination or experience.</p></div>').'</main>';}
elseif($page&&in_array($page['type'],['tour','attraction'])){$title=$page['title'];$description=$page['experience']['summary'];$body=detail($page,$visible,$s);}elseif($page){$title=$page['title'];$img=image($page);$body=breadcrumb($title).'<main id="main" class="container article-page"><p class="kicker">'.($page['type']==='guide'?'TRAVEL GUIDE':'BEST TOURS DUBAI').'</p><h1>'.e($title).'</h1>'.($page['type']==='guide'?'<p class="article-meta">By '.e($page['author']?:$s['name']).' · <time datetime="'.e($page['publishedAt']).'">'.dateLabel($page['publishedAt']).'</time></p>':'').($img?'<img class="article-hero" src="'.e($img['src']).'" alt="'.e($img['alt']).'">':'').'<article class="rich-content">'.cleanHtml($page['contentHtml']??'').'</article></main>';}else{$status=404;$title='Page not found';}
if($status===404)$body='<main id="main" class="container empty"><h1>'.e($title).'</h1><a class="button" href="/">Explore Dubai</a></main>';http_response_code($status);header('Content-Type: text/html;charset=utf-8');$cacheable=$status===200&&($_SERVER['REQUEST_METHOD']??'GET')==='GET'&&!$query&&!isset($_COOKIE['btd_session'])&&!in_array($path,['/booking.php','/thank-you','/search.php']);
if($cacheable){$ttl=300;foreach($pages as $item)if($item['status']==='published'&&!empty($item['publishedAt'])&&strtotime($item['publishedAt'])>time())$ttl=min($ttl,max(1,strtotime($item['publishedAt'])-time()));header('Cache-Control: public, max-age=0, must-revalidate');header('X-LiteSpeed-Cache-Control: public,max-age='.$ttl);}else{header('Cache-Control: private, no-store');header('X-LiteSpeed-Cache-Control: no-cache');}echo rewriteLinks(optimizeImages(document($s,$visible,$title,$body,$description,$script,seoHead($s,$page,$title,$description,$status,$path)),$visible),$visible);}
